local payload_get_queue = function()
local environments = {}
local seen = {}

local function add_environment(environment)
if type(environment) == 'table' and not seen[environment] then
seen[environment] = true
environments[#environments + 1] = environment
end
end

local ok_genv, genv = pcall(getgenv)
if ok_genv then add_environment(genv) end
add_environment(_G)

if type(getrenv) == 'function' then
local ok_renv, renv = pcall(getrenv)
if ok_renv then add_environment(renv) end
end

if type(getfenv) == 'function' then
local ok_fenv, fenv = pcall(getfenv, 0)
if ok_fenv then add_environment(fenv) end
end

local names = {
'queue_on_teleport',
'queueonteleport',
'queue_on_tp',
'queueontp',
'queueteleport',
}

for _, environment in ipairs(environments) do
for _, name in ipairs(names) do
local candidate = rawget(environment, name)
if type(candidate) == 'function' then
return candidate
end
end

for _, library_name in ipairs({ 'syn', 'fluxus' }) do
local library = rawget(environment, library_name)
if type(library) == 'table' then
local candidate = rawget(library, 'queue_on_teleport')
or rawget(library, 'queueonteleport')
if type(candidate) == 'function' then
return candidate
end
end
end
end

return nil
end

local Players = game:GetService('Players')
local player = Players.LocalPlayer
if not player then return end

local environment = getgenv()
local state = rawget(environment, '__ZenthraDeviceSpoofStateV2')

if type(state) ~= 'table' or state.version ~= 2 or state.game ~= game then
state = {
version = 2,
game = game,
revision = REVISION,
device = DEVICE,
target = TARGET,
}
rawset(environment, '__ZenthraDeviceSpoofStateV2', state)
elseif REVISION < state.revision then
return
else
state.revision = REVISION
state.device = DEVICE
state.target = TARGET
end

local stored_revision = tonumber(rawget(environment, '__ZenthraDeviceSpoofRevision')) or 0
if REVISION > stored_revision then
rawset(environment, '__ZenthraDeviceSpoofRevision', REVISION)
end
rawset(environment, 'ZENTHRA_DEVICE_SPOOF', DEVICE)

-- Arm the next hop now, while no teleport is in flight. Queue writes made
-- during a teleport handoff can wedge the process swap and crash the client;
-- a queued script only leaves this process on a real teleport, so a manual
-- leave still discards it.
local successor_queue = payload_get_queue()
if successor_queue then
pcall(successor_queue, SOURCE)
end

local ReplicatedStorage = game:GetService('ReplicatedStorage')
if not player:WaitForChild('PlayerGui', 30) then return end

local camera_deadline = os.clock() + 30
while not workspace.CurrentCamera and os.clock() < camera_deadline do
task.wait()
end
if not workspace.CurrentCamera then return end

if not ReplicatedStorage:WaitForChild('UserInputService', 30) then return end
local shared = ReplicatedStorage:WaitForChild('Shared', 30)
if not shared or not shared:WaitForChild('Statable', 30) then return end
local packages = ReplicatedStorage:WaitForChild('Packages', 30)
if not packages or not packages:WaitForChild('Signal', 30) then return end

local client_modules = ReplicatedStorage:WaitForChild('ClientGameModules', 30)
if not client_modules then return end
local device_module = client_modules:WaitForChild('DeviceListener', 30)
if not device_module then return end

local loaded, listener = pcall(require, device_module)
if not loaded or type(listener) ~= 'table' or type(listener.Observe) ~= 'function' then
return
end

if state.observeWrapped then return end
state.observeWrapped = true
state.listener = listener
state.originalObserve = listener.Observe

listener.Observe = function(self, callback)
if type(callback) ~= 'function' then
return state.originalObserve(self, callback)
end
